// Agoda — rank elements by value (LeetCode 1331), then ranks over a changing set.
public static class Ranking {
    // Each element replaced by its rank: 1 for the smallest, equal values share a rank, no gaps.
    public static int[] RankTransform(int[] arr) {
        if (arr == null) return Array.Empty<int>();
        var distinct = arr.Distinct().ToArray();
        Array.Sort(distinct);
        var rank = new Dictionary<int, int>(distinct.Length);
        for (int i = 0; i < distinct.Length; i++) rank[distinct[i]] = i + 1;
        var res = new int[arr.Length];
        for (int i = 0; i < arr.Length; i++) res[i] = rank[arr[i]];
        return res;
    }
}

// Values arrive and leave over time; Rank(v) = number of DISTINCT values currently present that are <= v.
// Values are in [0, MaxValue]. A Fenwick tree over value presence makes every operation O(log MaxValue).
public sealed class RankTracker {
    public const int MaxValue = 1_000_000;
    readonly int[] _tree = new int[MaxValue + 2];
    readonly int[] _count = new int[MaxValue + 1];       // multiplicity: a value is present while count > 0

    public void Add(int v) { Check(v); if (_count[v]++ == 0) Update(v, +1); }
    public void Remove(int v) { Check(v); if (_count[v] == 0) return; if (--_count[v] == 0) Update(v, -1); }
    public int Rank(int v) { Check(v); int s = 0; for (int i = v + 1; i > 0; i -= i & -i) s += _tree[i]; return s; }
    public int Distinct => Rank(MaxValue);

    void Update(int v, int d) { for (int i = v + 1; i < _tree.Length; i += i & -i) _tree[i] += d; }
    static void Check(int v) { if (v < 0 || v > MaxValue) throw new ArgumentOutOfRangeException(nameof(v)); }
}
